import React from 'react';

import type { PressEvent, KeyboardEvent } from '../../../core/types/events.js';
import type { RoleVariantType } from '../../../core/types/role-variant.js';

interface InformationOverlayTriggerProps {
  onPress?: (e: PressEvent) => void;
  isDisabled?: boolean;
  'aria-expanded'?: boolean | 'true' | 'false';
  'aria-haspopup'?:
    | boolean
    | 'menu'
    | 'listbox'
    | 'tree'
    | 'grid'
    | 'dialog'
    | 'true'
    | 'false';
  'aria-controls'?: string;
  onKeyDown?: (e: KeyboardEvent) => void;
}

export interface InformationOverlayContextType {
  variant: RoleVariantType;
  overlayTriggerProps: InformationOverlayTriggerProps;
  id: string;
  isOpen: boolean;
}

const DEFAULT_CONTEXT: InformationOverlayContextType = {
  variant: 'neutral',
  overlayTriggerProps: {},
  id: 'information-overlay',
  isOpen: false,
};

export const InformationOverlayContext =
  React.createContext<InformationOverlayContextType>(DEFAULT_CONTEXT);
